// PAPER CUT: doing this more than once, no generic finite condition for map,
// having to do the maximum thing
pub open spec fn segment_u_max(s: Set<SegmentId>) -> int
    decreases s.len()
{
    if s.len() == 0 {
        0
    } else {
        let x = s.choose();
        vstd::math::max(segment_u_max(s.remove(x)), x.uniq)
    }
}

