// give up on the recursive datatype and do a flat list of pointers and pointer permissions.

#[repr(C)]
#[derive(Copy)]
pub struct Node {
    pub ptr: *mut Node,
}

impl Clone for Node {
    fn clone(&self) -> Node {
        Node { ptr: self.ptr }
    }
}

